  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.header {
  margin-bottom: 2rem;
}

.eyebrow {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.75rem;
  font-weight: 700;
}

h1 {
  margin: 0.25rem 0 0.5rem;
